using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ── AddItem ───────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(2, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantityAndUsesLatestPrice()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 6.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(6.00m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllAppearInCart()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 2, 20m);

        Assert.AreEqual(2, _sut.Items.Count);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", qty, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -1m));
    }

    // ── RemoveItem ────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 10m);

        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(
            () => _sut.RemoveItem("NOPE"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.RemoveItem(sku!));
    }

    // ── CalculateTotal ────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _sut.AddItem("SKU-1", 3, 10.00m);

        Assert.AreEqual(30.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 5.00m);  // 10
        _sut.AddItem("B", 1, 7.50m);  //  7.50

        Assert.AreEqual(17.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 1, 100m);
        _sut.AddItem("B", 1, 50m);
        _sut.RemoveItem("A");

        Assert.AreEqual(50m, _sut.CalculateTotal());
    }

    // ── ApplyCoupon ───────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF",   50)]
    public void ApplyCoupon_ValidCode_DiscountsTotalByPercent(
        string code, int discountPercent)
    {
        _sut.AddItem("SKU-1", 1, 100m);
        _sut.ApplyCoupon(code);

        var expected = 100m - 100m * discountPercent / 100m;
        Assert.AreEqual(expected, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ValidCode_StoresAppliedCoupon()
    {
        _sut.ApplyCoupon("save10");

        Assert.AreEqual("SAVE10", _sut.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_AppliesDiscount()
    {
        _sut.AddItem("SKU-1", 1, 100m);
        _sut.ApplyCoupon("save20");

        Assert.AreEqual(80m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    public void ApplyCoupon_Twice_ThrowsInvalidOperation()
    {
        _sut.ApplyCoupon("SAVE10");

        Assert.ThrowsException<InvalidOperationException>(
            () => _sut.ApplyCoupon("SAVE20"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_InvalidCode_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    // ── Combined Scenarios ────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponCalculateTotal()
    {
        _sut.AddItem("WIDGET", 2, 25.00m); // 50
        _sut.AddItem("GADGET", 1, 30.00m); // 30
        _sut.ApplyCoupon("SAVE10");         // -10%

        Assert.AreEqual(72.00m, _sut.CalculateTotal());
        Assert.AreEqual("SAVE10", _sut.AppliedCoupon);
        Assert.AreEqual(2, _sut.Items.Count);
    }

    [TestMethod]
    public void ZeroPriceItem_DoesNotAffectTotal()
    {
        _sut.AddItem("FREE", 5, 0m);
        _sut.AddItem("PAID", 1, 20m);

        Assert.AreEqual(20m, _sut.CalculateTotal());
    }
}

